const $=s=>document.querySelector(s);let records=[],filter='Todos',db;const examples=[{id:'demo1',title:'¿Se mueven los mercados al azar?',topic:'Mercados',status:'Guía de inicio',notes:'Ejemplo orientativo para tu primera investigación.\n\nPregunta: ¿cómo se compara una serie de rendimientos con un paseo aleatorio?\n\n1. Elige una serie de precios y documenta su fuente.\n2. Calcula rendimientos logarítmicos: rₜ = ln(Pₜ/Pₜ₋₁).\n3. Compara su distribución y autocorrelación con un modelo aleatorio.\n4. Describe las diferencias y las limitaciones de tus datos.\n\nNo contiene resultados reales. Sustituye esta guía con tus propios hallazgos.',date:'2026-10-27',demo:true},{id:'demo2',title:'Una economía hecha de conexiones',topic:'Redes',status:'Guía de inicio',notes:'Ejemplo orientativo.\n\nRepresenta empresas o sectores como nodos y sus intercambios como enlaces. Comienza con una red pequeña, calcula el grado de cada nodo y explora qué ocurre al retirar uno.\n\nPregunta: ¿qué conexiones parecen importantes para la estructura de la red?\n\nRegistra las suposiciones: una red ilustrativa no demuestra cómo funciona una economía real.',date:'2026-10-27',demo:true},{id:'demo3',title:'La distribución de la riqueza bajo la lupa',topic:'Estadística',status:'Guía de inicio',notes:'Ejemplo orientativo.\n\nExplora un modelo de intercambio en el que varios agentes intercambian cantidades aleatorias conservando la riqueza total.\n\nObserva el histograma después de muchas iteraciones. Compara reglas de intercambio distintas y registra cómo cambian los resultados.\n\nUna distribución simulada depende de sus supuestos; no debe interpretarse automáticamente como evidencia empírica.',date:'2026-10-27',demo:true}];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('entropia-archive',1);r.onupgradeneeded=()=>r.result.createObjectStore('entries',{keyPath:'id'});r.onsuccess=()=>{db=r.result;resolve()};r.onerror=()=>reject(r.error)})}function read(){return new Promise((resolve,reject)=>{const r=db.transaction('entries').objectStore('entries').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}function save(items){return new Promise((resolve,reject)=>{const tx=db.transaction('entries','readwrite');for(const item of items)tx.objectStore('entries').put(item);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function visual(topic){let shapes='';if(topic==='Mercados'){for(let i=0;i<40;i++){const y=90-30*Math.sin(i*.16)-i*.8;shapes+=`<line x1="${i*10}" y1="${y-14}" x2="${i*10}" y2="${y+16}" stroke="rgba(34,211,238,0.3)"/><rect x="${i*10-2}" y="${y-6}" width="4" height="12" fill="#22d3ee"/>`}shapes+='<path d="M0 125 Q90 120 130 85 T230 65 T400 20" fill="none" stroke="#38bdf8" stroke-width="2"/>'}else if(topic==='Redes'){for(let i=0;i<26;i++){const x=200+Math.cos(i*2.4)*((i*19)%135),y=80+Math.sin(i*2.4)*((i*11)%63);shapes+=`<line x1="200" y1="80" x2="${x}" y2="${y}" stroke="rgba(59,130,246,0.35)" stroke-width=".8"/><circle cx="${x}" cy="${y}" r="3" fill="#818cf8"/>`}shapes+='<circle cx="200" cy="80" r="8" fill="#22d3ee"/>'}else{for(let i=0;i<42;i++){const h=100*Math.exp(-(((i-21)/9)**2));shapes+=`<rect x="${i*9+12}" y="${135-h}" width="6" height="${h}" fill="#3b82f6" opacity=".4"/>`}shapes+='<path d="M10 134 Q110 135 150 65 Q200 -15 250 65 Q290 135 395 134" fill="none" stroke="#22d3ee" stroke-width="2"/>'}return `<svg viewBox="0 0 400 160" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${shapes}</svg>`}
function render(){const q=$('#search').value.toLocaleLowerCase();let list=[...records,...examples].filter(r=>(filter==='Todos'||r.topic===filter)&&`${r.title} ${r.notes}`.toLocaleLowerCase().includes(q));list.sort($('#sort').value==='az'?(a,b)=>a.title.localeCompare(b.title):(a,b)=>Number(a.demo||false)-Number(b.demo||false)||b.date.localeCompare(a.date));$('#total').textContent=String(records.length).padStart(2,'0');$('#count').textContent=`${list.length} entradas · ${records.length} propias · guías ilustrativas incluidas`;$('#cards').innerHTML=list.map(r=>`<button class="card" data-id="${escapeHTML(r.id)}"><div class="card-visual" style="background:${r.topic==='Redes'?'#e8edf2':r.topic==='Estadística'?'#f0ece3':'#e6eee7'}">${visual(r.topic)}<span class="pill">${r.demo?'GUÍA ILUSTRATIVA':'MI INVESTIGACIÓN'} · JUNIOR</span></div><div class="card-body"><span class="eyebrow">${escapeHTML(r.topic)}</span><h3>${escapeHTML(r.title)}</h3><p>${escapeHTML(r.notes)}</p><div class="card-bottom"><span class="status">● ${escapeHTML(r.status)}</span><span>${new Date(r.date).toLocaleDateString('es-PE',{day:'numeric',month:'short',year:'numeric'})} ↗</span></div></div></button>`).join('')+`<button class="card new-card" id="newCard"><strong>＋</strong><span>Una nueva pregunta empieza aquí</span><small>Añadir investigación</small></button>`;$('#newCard').onclick=()=>$('#editor').showModal();document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>showEntry([...records,...examples].find(r=>r.id===b.dataset.id)))}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function showEntry(r){$('#detailTopic').textContent=r.topic+(r.demo?' / GUÍA ILUSTRATIVA':' / MI INVESTIGACIÓN');$('#detailTitle').textContent=r.title;$('#detailMeta').textContent=r.status;$('#detailNotes').textContent=r.notes;$('#detailActions').replaceChildren();if(r.file){const b=document.createElement('button');b.className='button';b.textContent='Descargar '+r.file.name;b.onclick=()=>download(r.file.blob,r.file.name);$('#detailActions').append(b)}if(!r.demo){const b=document.createElement('button');b.className='text-link';b.textContent='Eliminar investigación';b.onclick=()=>{if(!confirm('¿Eliminar esta investigación y su adjunto de este navegador?'))return;const tx=db.transaction('entries','readwrite');tx.objectStore('entries').delete(r.id);tx.oncomplete=async()=>{records=await read();render();$('#detail').close();toast('Investigación eliminada')};tx.onerror=()=>toast('No se pudo eliminar')};$('#detailActions').append(b)}$('#detail').showModal()}
document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#addTop').onclick=()=>$('#editor').showModal();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render()});$('#search').oninput=render;$('#sort').onchange=render;
$('#entryForm').onsubmit=async e=>{e.preventDefault();const f=e.target,file=f.elements.file.files[0];$('#formError').textContent='';if(file?.size>10*1024*1024){$('#formError').textContent='El archivo supera los 10 MB.';return}const title=f.elements.title.value.trim(),notes=f.elements.notes.value.trim();if(!title||!notes){$('#formError').textContent='Escribe un título y unas notas.';return}try{await save([{id:crypto.randomUUID(),title,notes,topic:f.elements.topic.value,status:f.elements.status.value,date:new Date().toISOString(),file:file?{name:file.name,blob:file}:null}]);records=await read();render();$('#editor').close();f.reset();toast('Investigación guardada')}catch{$('#formError').textContent='No se pudo guardar. Revisa el espacio y los permisos del navegador.'}};
const toDataURL=blob=>new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(blob)});$('#export').onclick=async()=>{try{const entries=await Promise.all(records.map(async r=>({...r,file:r.file?{name:r.file.name,data:await toDataURL(r.file.blob)}:null})));download(new Blob([JSON.stringify({version:1,entries,progress:JSON.parse(localStorage.getItem('entropia-progress')||'[]')})],{type:'application/json'}),'entropia-respaldo.json');toast('Copia de respaldo exportada')}catch{toast('No se pudo exportar la copia')}};$('#import').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.entries))throw Error();const imported=await Promise.all(data.entries.map(async r=>{if(typeof r.title!=='string'||typeof r.notes!=='string'||!['Mercados','Redes','Estadística'].includes(r.topic)||typeof r.status!=='string'||!Number.isFinite(Date.parse(r.date)))throw Error();let attachment=null;if(r.file){if(typeof r.file.name!=='string'||!/^data:[^,]*;base64,/.test(r.file.data))throw Error();const blob=await(await fetch(r.file.data)).blob();if(blob.size>10485760)throw Error();attachment={name:r.file.name,blob}}return {...r,id:crypto.randomUUID(),demo:false,file:attachment}}));await save(imported);if(Array.isArray(data.progress)){localStorage.setItem('entropia-progress',JSON.stringify(data.progress.filter(x=>[0,1,2].includes(x))));renderProgress()}records=await read();render();toast('Copia importada; se añadieron '+imported.length+' investigaciones')}catch{toast('No se pudo importar. Comprueba el formato y el espacio disponible.')}e.target.value=''};
function renderProgress(){let p=[];try{p=JSON.parse(localStorage.getItem('entropia-progress')||'[]')}catch{}document.querySelectorAll('[data-step]').forEach(b=>{const done=p.includes(+b.dataset.step);b.classList.toggle('done',done);b.setAttribute('aria-pressed',String(done));b.querySelector('b').textContent=done?'Completado ✓':'Marcar como completado ○';b.onclick=()=>{const i=+b.dataset.step;try{localStorage.setItem('entropia-progress',JSON.stringify(done?p.filter(x=>x!==i):[...p,i]));renderProgress()}catch{toast('No se pudo guardar el progreso')}}})}renderProgress();
let walk=[];function simulate(){walk=[100];const amp=+$('#vol').value;for(let i=1;i<=200;i++)walk.push(walk[i-1]+(Math.random()*2-1)*amp);drawChart()}function size(canvas){const rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);return {ctx,w:rect.width,h:rect.height}}function drawChart(){const {ctx,w,h}=size($('#chart'));if(!w)return;const min=Math.min(...walk)-10,max=Math.max(...walk)+10;ctx.font='10px JetBrains Mono, monospace';for(let i=0;i<5;i++){const y=22+i*(h-45)/4;ctx.strokeStyle='rgba(59, 130, 246, 0.18)';ctx.beginPath();ctx.moveTo(35,y);ctx.lineTo(w-8,y);ctx.stroke();ctx.fillStyle='#64748b';ctx.fillText(Math.round(max-(max-min)*i/4),0,y+3)}const xy=walk.map((v,i)=>[35+i*(w-45)/200,22+(max-v)/(max-min)*(h-45)]);ctx.beginPath();xy.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.strokeStyle='#22d3ee';ctx.lineWidth=2;ctx.stroke();ctx.lineTo(w-10,h-23);ctx.lineTo(35,h-23);ctx.closePath();const g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'rgba(34, 211, 238, 0.35)');g.addColorStop(1,'rgba(37, 99, 235, 0)');ctx.fillStyle=g;ctx.fill()}
$('#simulate').onclick=simulate;$('#vol').oninput=()=>{$('#volOut').value=$('#vol').value;simulate()};simulate();
let t=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function network(){const {ctx,w,h}=size($('#network'));const points=[];for(let i=0;i<105;i++){const theta=i*2.39996,rad=Math.sqrt(i/105),x=Math.cos(theta+t)*rad,y=Math.sin(theta+t)*rad,z=Math.sin(i*1.72+t);points.push({x:w*.54+x*w*.37,y:h*.43+y*h*.32+z*14,r:1.2+(1+z)*1.5})}for(let i=0;i<points.length;i++){for(let j=i+1;j<points.length;j++){const a=points[i],b=points[j],dist=Math.hypot(a.x-b.x,a.y-b.y);if(dist<w*.16){ctx.strokeStyle=`rgba(34,211,238,${.35*(1-dist/(w*.16))})`;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}}points.forEach(p=>{ctx.fillStyle='#22d3ee';ctx.shadowColor='rgba(34,211,238,0.8)';ctx.shadowBlur=6;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0});t+=.001;if(!reduced)setTimeout(()=>requestAnimationFrame(network),60)}network();window.addEventListener('resize',()=>{drawChart();if(reduced)network()});openDB().then(async()=>{records=await read();render()}).catch(()=>{render();toast('Almacenamiento no disponible en este navegador')});
